<script setup lang="ts">
import { computed } from 'vue'; import ChartBase from './ChartBase.vue'; import type { EChartsCoreOption } from 'echarts/core'
export interface TrendSeries { name:string; data:Array<number|null>; unit?:string; colorToken?:string }
const props=withDefaults(defineProps<{labels:string[];series:TrendSeries[];targetLine?:number|null;height?:number|string}>(),{height:300,targetLine:null}); const emit=defineEmits<{point:[index:number]}>()
const css=(name:string)=>getComputedStyle(document.documentElement).getPropertyValue(name).trim()
const option=computed<EChartsCoreOption>(()=>({animationDuration:200,color:props.series.map(row=>css(row.colorToken||'--brand')),grid:{left:48,right:20,top:42,bottom:36},legend:{top:0,textStyle:{color:css('--text-2'),fontSize:12}},tooltip:{trigger:'axis',axisPointer:{type:'cross'},valueFormatter:(value:unknown)=>value==null?'未记录':String(value)},xAxis:{type:'category',data:props.labels,boundaryGap:false,axisLine:{lineStyle:{color:css('--border')}},axisLabel:{color:css('--text-3'),fontSize:11}},yAxis:{type:'value',scale:true,splitLine:{lineStyle:{color:css('--border')}},axisLabel:{color:css('--text-3'),fontSize:11}},series:props.series.map((row,index)=>({name:row.name,type:'line',data:row.data,smooth:.25,connectNulls:false,showSymbol:false,symbolSize:7,lineStyle:{width:index===0?3:2},emphasis:{focus:'series'},markLine:index===0&&props.targetLine!=null?{silent:true,symbol:'none',label:{formatter:`目标 ${props.targetLine}`},lineStyle:{type:'dashed',color:css('--accent')},data:[{yAxis:props.targetLine}]}:undefined}))}))
</script>
<template><ChartBase :option="option" :height="height" :empty="!labels.length||!series.some(row=>row.data.some(value=>value!=null))" @click="(params:any)=>emit('point',params.dataIndex)"/></template>
